const base = "http://127.0.0.1:8799"; const password = "StorekeeperTest!2026";
const ok = (v: unknown, m: string) => { if (!v) throw Error(m); console.log(`PASS ${m}`); };
async function login(username: string) { const r = await fetch(`${base}/api/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ username, password }) }); ok(r.status === 204, `${username} login`); const cookie = r.headers.get("set-cookie")!.split(";")[0]; const s = await fetch(`${base}/api/session`, { headers: { cookie } }); return { cookie, csrf: (await s.json()).csrfToken }; }
const call = (c: any, p: string, m = "GET", b?: any) => fetch(`${base}${p}`, { method:m, headers:{ cookie:c.cookie, "x-csrf-token":c.csrf, ...(b===undefined?{}:{"content-type":"application/json"}) }, body:b===undefined?undefined:JSON.stringify(b) });
const admin=await login("Admin"), rep=await login("Rep A"), store=await login("Storekeeper Status");
const buyer=(await (await call(admin,"/api/buyers")).json())[0], product=(await (await call(admin,"/api/products")).json())[0];
let r=await call(rep,"/api/quotations","POST",{idempotencyKey:"66666666-6666-4666-8666-666666666666",buyerId:buyer.id,quotationDate:"2026-11-08",items:[{productId:product.id,quantity:1,unitPriceMinor:product.price_minor}]}); ok(r.status===201,"Rep creates age-test order"); const order=await r.json();
let detail=await (await call(store,`/api/quotations/${order.id}`)).json(); r=await call(store,`/api/quotations/${order.id}/packing`,"PUT",{version:detail.dispatch_version,items:detail.items.map((x:any)=>({productId:x.product_id,checked:true}))}); ok(r.status===200,"Storekeeper packs age-test order"); r=await call(store,`/api/quotations/${order.id}/dispatch`,"POST",{}); ok(r.status===200,"Storekeeper dispatches age-test order");
